// Pure template tests — no DB, no schema, no requests.
//
// These guard two things the rest of the suite cannot see: that the invite
// stopped carrying a credential, and that the plaintext part is genuinely
// plaintext rather than escaped HTML.

import { describe, it, expect } from 'vitest';
import {
  adminDigestEmail,
  approvalDecisionEmail,
  EmailContent,
  inviteEmail,
  passwordResetEmail,
  taskAssignedEmail,
  testEmail,
  weeklyReminderEmail,
} from '../src/services/email-templates';

const BASE = 'https://utrockets-onboarding.com';

/** The passcode shape generated by generatePasscode(). */
const PASSCODE_RE = /[A-Z2-9]{4}-[A-Z2-9]{4}-[A-Z2-9]{4}/;

const ALL: [string, EmailContent][] = [
  ['invite', inviteEmail({ name: 'New Hire', email: 'a@utoledo.edu', baseUrl: BASE, expiryDays: 14 })],
  [
    'passwordReset',
    passwordResetEmail({
      name: null,
      email: 'a@utoledo.edu',
      resetUrl: `${BASE}/reset-password?token=abc`,
      expiryMinutes: 60,
    }),
  ],
  [
    'taskAssigned',
    taskAssignedEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      taskTitle: 'Parking pass',
      taskDescription: 'Collect it from the office',
      assignedByEmail: 'hr@utoledo.edu',
      baseUrl: BASE,
    }),
  ],
  [
    'weeklyReminder',
    weeklyReminderEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      tasks: [{ title: 'Parking pass', phase: 'first-week', priority: 'required' }],
      baseUrl: BASE,
    }),
  ],
  [
    'approvalDecision',
    approvalDecisionEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      taskTitle: 'Parking pass',
      approved: true,
      note: 'Looks good',
      baseUrl: BASE,
    }),
  ],
  [
    'adminDigest',
    adminDigestEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      users: [{ email: 'b@utoledo.edu', name: 'B', open_tasks: 3 }],
      baseUrl: BASE,
    }),
  ],
  ['test', testEmail({ email: 'a@utoledo.edu', fromAddress: 'onboarding@mail.example.com' })],
];

describe('every template', () => {
  it.each(ALL)('%s has a non-empty subject, html and text part', (_name, content) => {
    expect(content.subject.trim()).not.toBe('');
    expect(content.html.trim()).not.toBe('');
    expect(content.text.trim()).not.toBe('');
  });

  it.each(ALL)('%s keeps markup out of the text part', (_name, content) => {
    expect(content.text).not.toContain('<div');
    expect(content.text).not.toContain('style=');
  });

  // The text renderer must never call escapeHtml. A plaintext body reading
  // "Rockets &amp; Co" is the classic bug this guards.
  it.each(ALL)('%s does not HTML-escape the text part', (_name, content) => {
    for (const entity of ['&amp;', '&lt;', '&gt;', '&quot;']) {
      expect(content.text).not.toContain(entity);
    }
  });

  it.each(ALL)('%s keeps the subject on one line', (_name, content) => {
    expect(content.subject).not.toMatch(/[\r\n]/);
  });
});

describe('inviteEmail', () => {
  it('carries no passcode in either part', () => {
    // The signature no longer accepts one, so this asserts intent rather than
    // catching a live leak — it is what fails if someone puts it back.
    const content = inviteEmail({
      name: 'New Hire',
      email: 'new.hire@utoledo.edu',
      baseUrl: BASE,
      expiryDays: 14,
    });
    expect(content.html).not.toMatch(PASSCODE_RE);
    expect(content.text).not.toMatch(PASSCODE_RE);
    expect(content.text).toMatch(/not sent by email/i);
  });

  it('shows the destination of its link so anchor text and href agree', () => {
    const content = inviteEmail({
      name: null,
      email: 'a@utoledo.edu',
      baseUrl: BASE,
      expiryDays: 14,
    });
    // The URL appears as visible text, not only inside href="…".
    expect(content.html).toContain(`Or copy this link: ${BASE}`);
    expect(content.text).toContain(BASE);
  });

  it('falls back to the local part when no name is set', () => {
    const content = inviteEmail({
      name: null,
      email: 'jane.doe@utoledo.edu',
      baseUrl: BASE,
      expiryDays: 14,
    });
    expect(content.text).toContain('Hi jane.doe,');
  });
});

describe('escaping', () => {
  it('escapes hostile input in html and leaves it raw in text', () => {
    const content = taskAssignedEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      taskTitle: '<script>alert(1)</script>',
      taskDescription: 'Tom & Jerry said "hi"',
      assignedByEmail: 'hr@utoledo.edu',
      baseUrl: BASE,
    });
    expect(content.html).toContain('&lt;script&gt;');
    expect(content.html).not.toContain('<script>');
    // The two renderers must diverge exactly here.
    expect(content.text).toContain('<script>alert(1)</script>');
    expect(content.text).toContain('Tom & Jerry said "hi"');
  });

  it('bounds and flattens subjects built from admin-entered text', () => {
    const content = taskAssignedEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      taskTitle: 'x'.repeat(300) + '\nBcc: attacker@example.com',
      taskDescription: null,
      assignedByEmail: 'hr@utoledo.edu',
      baseUrl: BASE,
    });
    expect(content.subject.length).toBeLessThanOrEqual(120);
    expect(content.subject).not.toMatch(/[\r\n]/);
  });
});

describe('list rendering', () => {
  it('lists every task in the reminder text part', () => {
    const content = weeklyReminderEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      tasks: [
        { title: 'Parking pass', phase: 'first-week', priority: 'required' },
        { title: 'Benefits form', phase: 'first-month', priority: 'optional' },
      ],
      baseUrl: BASE,
    });
    expect(content.text).toContain('- Parking pass (first week, required)');
    expect(content.text).toContain('- Benefits form (first month)');
  });

  it('lists every person in the digest text part', () => {
    const content = adminDigestEmail({
      name: 'A',
      email: 'a@utoledo.edu',
      users: [
        { email: 'b@utoledo.edu', name: 'B Person', open_tasks: 3 },
        { email: 'c@utoledo.edu', name: null, open_tasks: 1 },
      ],
      baseUrl: BASE,
    });
    expect(content.text).toContain('- B Person <b@utoledo.edu> — 3 open');
    expect(content.text).toContain('- c@utoledo.edu <c@utoledo.edu> — 1 open');
  });
});
